package com.bedlessfighter.necroManager.commands;
import com.bedlessfighter.necroManager.managers.*;import org.bukkit.Bukkit;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.jetbrains.annotations.NotNull;
public final class ClearInventoryCommand implements CommandExecutor {
 @Override public boolean onCommand(@NotNull CommandSender s,@NotNull Command c,@NotNull String[] a){if(a.length>1){MessageManager.sendRaw(s,"&cUsage: /clearinventory [player]");return true;}if(!PermissionManager.has(s,"necromanager.clearinventory")){MessageManager.send(s,"messages.no-perm","&cNo permission.");return true;}Player t;if(a.length==1){if(!PermissionManager.has(s,"necromanager.clearinventory.others")){MessageManager.send(s,"messages.no-perm","&cNo permission to clear others.");return true;}t=Bukkit.getPlayerExact(a[0]);if(t==null){MessageManager.send(s,"messages.player-not-found","&cPlayer not online.");return true;}}else if(s instanceof Player p)t=p;else{MessageManager.send(s,"messages.player-required","&cConsole must specify a player.");return true;}t.getInventory().clear();t.getInventory().setArmorContents(null);t.getInventory().setItemInOffHand(null);t.updateInventory();MessageManager.sendRaw(s,"&aCleared "+t.getName()+"'s inventory.");if(!t.equals(s))MessageManager.sendRaw(t,"&eYour inventory was cleared by staff.");return true;}
}